//! Export des schémas JSON de P-08 (spec P-00 §5, critère 6).

use rgaa_analysis::{analysis_error, Result};
use schemars::schema_for;
use serde::Serialize;
use serde_json::Value;

/// Schémas de toutes les formes de `mesures` et des échanges LLM versionnés.
pub fn schemas() -> Result<Value> {
    Ok(serde_json::json!({
        "$comment": "Generated by `cargo run -p rgaa-analysis-text --bin dump-text-schemas`. Do not edit by hand.",
        "mesures": {
            "texte": to_value(schema_for!(crate::mesures::Mesures))?,
        },
        "llm": {
            "requete": to_value(schema_for!(crate::llm::LlmRequest))?,
            "reponse": to_value(schema_for!(crate::llm::LlmResponse))?,
        },
        "entree": to_value(schema_for!(crate::snapshot::TextSnapshot))?,
    }))
}

fn to_value(schema: impl Serialize) -> Result<Value> {
    serde_json::to_value(schema)
        .map_err(|error| analysis_error("text", format!("schéma invalide : {error}")))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn aucun_schema_ne_declare_de_statut() {
        let document = schemas().expect("schémas");
        let json = serde_json::to_string(&document).expect("sérialisation");
        assert!(!json.contains("\"status\""));
        assert!(!json.contains("\"verdict\""));
        assert!(document["llm"]["requete"].is_object());
    }
}
